class Solution {
  public int colorTheGrid(int m, int n) {
    final int MOD = 1_000_000_007;
    java.util.List<Integer> states = new java.util.ArrayList<>();
    int total = 1;
    for (int i = 0; i < m; i++) total *= 3;
    for (int x = 0; x < total; x++) {
      int t = x, prev = -1;
      boolean ok = true;
      for (int i = 0; i < m; i++) {
        int d = t % 3;
        t /= 3;
        if (d == prev) ok = false;
        prev = d;
      }
      if (ok) states.add(x);
    }
    long[] dp = new long[states.size()];
    java.util.Arrays.fill(dp, 1);
    for (int col = 1; col < n; col++) {
      long[] next = new long[dp.length];
      for (int i = 0; i < states.size(); i++)
        for (int j = 0; j < states.size(); j++)
          if (compatible(states.get(i), states.get(j), m)) next[j] = (next[j] + dp[i]) % MOD;
      dp = next;
    }
    long ans = 0;
    for (long v : dp) ans = (ans + v) % MOD;
    return (int) ans;
  }

  private boolean compatible(int a, int b, int m) {
    for (int i = 0; i < m; i++) {
      if (a % 3 == b % 3) return false;
      a /= 3;
      b /= 3;
    }
    return true;
  }
}
